            (".theme-toggle .sun, .theme-toggle[data-mode=\"dark\"] .moon { display: none; }", "...the switch showing the moon in light mode and the sun in dark mode. `js/theme.js` sets `data-mode`.", ".theme-toggle[data-mode=\"dark\"] .sun { display: block; }"),
            (".live-badge {", "The green Live badge..."),
